//! Param connection retains actual identities and owner metadata.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><div id=target>Fallback param<param id=param name=seed value=seed type=seed valuetype=seed><span id=tail>tail</span></div><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://param-connection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]fn param_connection_native_created_append_reorder_remove_control(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var target=document.getElementById('target'),first=target.firstChild,tail=document.getElementById('tail'),x=document.createElement('param');x.name='created';x.value='native';x.type='MiXeD';x.valueType='unknown';var attr=x.getAttributeNode('value');target.appendChild(x);if(x.parentNode!==target||x.ownerDocument!==document||target.lastChild!==x||x.getAttributeNode('value')!==attr||x.value!=='native')throw 'created native connection';target.insertBefore(x,first);if(target.firstChild!==x||x.nextSibling!==first||attr.ownerElement!==x)throw 'native reorder';target.removeChild(x);if(x.parentNode!==null||target.firstChild!==first||x.value!=='native'||x.getAttributeNode('value')!==attr||document.getElementById('neighbor').value!=='seed')throw 'native removal';
"#);}
#[test]fn param_connection_inert_insert_preserves_node_attr_and_destination_owner(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var target=document.getElementById('target'),tail=document.getElementById('tail'),owner=new Document(),x=owner.createElementNS('http://www.w3.org/1999/xhtml','param');x.name='A\udfffZ';x.value='A\ud800Z';x.type='MiXeD';x.valueType='unknown';var attr=x.getAttributeNode('value');target.insertBefore(x,tail);if(!(x instanceof HTMLParamElement)||x.parentNode!==target||x.nextSibling!==tail||x.ownerDocument!==document||attr.ownerDocument!==document||attr.ownerElement!==x||x.getAttributeNode('value')!==attr||x.name!=='A\udfffZ'||x.value!=='A\ud800Z'||x.type!=='MiXeD'||x.valueType!=='unknown')throw 'inert Param owner transfer';target.removeChild(x);if(x.ownerDocument!==document||x.parentNode!==null||attr.ownerDocument!==document)throw 'transferred removal';
"#);}
#[test]fn param_connection_native_clone_template_parking_roundtrip_keeps_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var target=document.getElementById('target'),source=document.getElementById('param'),x=source.cloneNode(false),attr=x.getAttributeNode('value'),template=document.createElement('template');template.content.appendChild(x);if(x.parentNode!==template.content||x.ownerDocument!==template.content.ownerDocument||attr.ownerDocument!==x.ownerDocument||x.getAttributeNode('value')!==attr||x.value!=='seed')throw 'Param native parking';target.appendChild(template.content);if(x.parentNode!==target||x.ownerDocument!==document||attr.ownerDocument!==document||x.getAttributeNode('value')!==attr||template.content.firstChild!==null||source.value!=='seed')throw 'Param parking roundtrip';
"#);}

#[test]
fn param_connection_storage_work_copy_and_deadline_refusals_preserve_identity_and_recover(){
 for parking in [false,true]{for mode in 0..4{
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if parking{
   "var target=document.createElement('template').content,source=document.getElementById('param').cloneNode(false);"
  }else{
   "var target=document.getElementById('target'),owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','param');"
  });
  run(&mut d,&mut f,&mut p,"source.name='held';source.value='retained';source.type='MiXeD';source.valueType='unknown';var attr=source.getAttributeNode('value'),watch=new MutationObserver(function(){});watch.observe(target,{childList:true});var originalOwner=source.ownerDocument;");
  p.state.rebuild(&d).unwrap();let tree=format!("{:?}",d.nodes);
  let before=(p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),Bridge{doc: &mut d,forms: &mut f,state: &mut p.state}.inert_node_count(),p.state.attributes.len(),p.state.detached_nodes.clone());
  let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};
  let error=p.runtime.execute("target.appendChild(source);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();
  assert!(error.contains("work")||error.contains("allowance")||error.contains("limit")||error.contains("bound")||error.contains("time"),"{parking}/{mode}: {error}");
  assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),Bridge{doc: &mut d,forms: &mut f,state: &mut p.state}.inert_node_count(),p.state.attributes.len(),p.state.detached_nodes.clone()),before);
  p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();
  run(&mut d,&mut f,&mut p,"if(source.parentNode!==null||source.ownerDocument!==originalOwner||source.getAttributeNode('value')!==attr||attr.ownerElement!==source||source.value!=='retained'||source.type!=='MiXeD'||source.valueType!=='unknown'||watch.takeRecords().length)throw 'atomic Param transfer refusal';target.appendChild(source);var records=watch.takeRecords();if(source.parentNode!==target||source.ownerDocument!==target.ownerDocument||attr.ownerDocument!==target.ownerDocument||source.getAttributeNode('value')!==attr||source.value!=='retained'||source.type!=='MiXeD'||source.valueType!=='unknown'||records.length!==1)throw 'fresh Param transfer recovery '+[source.parentNode===target,source.ownerDocument===target.ownerDocument,attr.ownerDocument===target.ownerDocument,source.getAttributeNode('value')===attr,records.length].join(',');");
  assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.state.images.has_changes());
 }}
}

#[test]
fn param_connection_saved_child_append_revalidates_origin_before_transferring_owner(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','param'),target=document.getElementById('target'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);source.value='saved';var saved=frame.contentWindow.Node.prototype.appendChild,attr=source.getAttributeNode('value');");
 p.set_location(&crate::navigation::address("https://other-param.test/",&crate::navigation::Location::home()).unwrap());
 let tree=format!("{:?}",d.nodes);let before=(p.state.retained,p.state.dom_commits);p.begin_job();
 let error=p.runtime.execute("saved.call(target,source);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");
 assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits),before);
 p.set_location(&crate::navigation::address("https://param-connection.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();
 run(&mut d,&mut f,&mut p,"if(source.parentNode!==null||source.ownerDocument!==owner||attr.ownerDocument!==owner||source.value!=='saved')throw 'denied transfer preserves owner';if(saved.call(target,source)!==source||source.ownerDocument!==document||source.parentNode!==target||source.getAttributeNode('value')!==attr||attr.ownerDocument!==document||source.value!=='saved')throw 'saved transfer fresh recovery';");
}


#[test]fn param_connection_parsed_and_fragment_clones_roundtrip(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var target=document.getElementById('target'),owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','param');source.value='raw\udfff';source.name='n';source.type='MiXeD';source.valueType='unknown';var x=source.cloneNode(false),attr=x.getAttributeNode('value');target.appendChild(x);if(x===source||x.ownerDocument!==document||attr.ownerDocument!==document||x.value!=='raw\udfff'||source.ownerDocument!==owner)throw 'inert copy connection';target.removeChild(x);var template=document.createElement('template');template.content.appendChild(x);target.appendChild(template.content);if(x.parentNode!==target||x.getAttributeNode('value')!==attr||attr.ownerElement!==x)throw 'copy roundtrip';template.innerHTML='<param name="parsed" value="v" type="MiXeD" valuetype="unknown">';var fragment=template.content,parsed=fragment.firstChild,parsedAttr=parsed.getAttributeNode('value'),donor=fragment.cloneNode(true),cloned=donor.firstChild;target.appendChild(fragment);target.appendChild(donor);if(fragment.firstChild!==null||donor.firstChild!==null||parsed===cloned||parsed.parentNode!==target||cloned.parentNode!==target||parsed.ownerDocument!==document||cloned.ownerDocument!==document||parsed.getAttributeNode('value')!==parsedAttr||parsedAttr.ownerDocument!==document||cloned.name!=='parsed'||cloned.value!=='v'||cloned.type!=='MiXeD'||cloned.valueType!=='unknown')throw 'parsed clone connection';
"#);assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.state.images.has_changes());}
#[test]fn param_connection_active_and_foreign_sources_refuse_atomically(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var target=document.getElementById('target'),template=document.createElement('template');template.innerHTML='<param value="held" onclick="return 1;">';var source=template.content.firstChild,owner=source.ownerDocument,attr=source.getAttributeNode('value'),watch=new MutationObserver(function(){});watch.observe(target,{childList:true});var caught=false;try{target.appendChild(source);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||source.parentNode!==template.content||source.ownerDocument!==owner||attr.ownerDocument!==owner||source.getAttributeNode('value')!==attr||watch.takeRecords().length)throw 'active transfer refusal';var foreign=owner.createElementNS('urn:param','param');caught=false;try{target.appendChild(foreign);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||foreign.parentNode!==null||foreign.ownerDocument!==owner||watch.takeRecords().length)throw 'foreign transfer refusal';var clean=owner.createElementNS('http://www.w3.org/1999/xhtml','param');clean.value='safe';target.appendChild(clean);if(clean.ownerDocument!==document||clean.value!=='safe'||watch.takeRecords().length!==1)throw 'safe fresh recovery';
"#);assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.state.images.has_changes());}
